solution:
const middlewares = [
  (next) => { console.log("auth"); next() },
  (next) => { console.log("log"); next() },
  () => { console.log("handler") },
]
function executar(lista) {
  const avancar = (i) => { if (lista[i]) lista[i](() => avancar(i + 1)) }
  avancar(0)
}
executar(middlewares)

