solution:
class Conta:
    def __init__(self, saldo):
        self.saldo = saldo

    def depositar(self, valor):
        self.saldo += valor

    def sacar(self, valor):
        if valor > self.saldo:
            print("Saldo insuficiente")
            return
        self.saldo -= valor

c = Conta(100)
c.depositar(100)
c.sacar(50)
print(c.saldo)
c.sacar(500)

